#!/usr/bin/env python3
"""Writes src/layout/fontmetrics.js: advances (em) of printable ASCII for Barlow Condensed 400 / 500 / 600 / 700, read from the @fontsource woff files.
Usage: python3 tools/extract-font-advances.py <folder with barlow-condensed-latin-<w>-normal.woff>"""
import sys, json
from fontTools.ttLib import TTFont
src = sys.argv[1]
out = {}
for w in (400, 500, 600, 700):
    f = TTFont(f'{src}/barlow-condensed-latin-{w}-normal.woff')
    c = f.getBestCmap(); u = f['head'].unitsPerEm
    out[w] = {chr(i): round(f['hmtx'][c[i]][0] / u, 4) for i in range(32, 127)}
with open('src/layout/fontmetrics.js', 'w') as o:
    o.write("// Generated by tools/extract-font-advances.py (Barlow Condensed, SIL OFL): advance of each printable ASCII character, in em, per weight.\n")
    o.write("// Used to lay out chord symbols without a browser (the font is proportional, unlike the monospace one it replaces).\n")
    o.write("export const BARLOW_ADVANCES = " + json.dumps(out, ensure_ascii=False) + ";\n")
